// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Review reproducers for standard-pipeline optimizer changes on the GH-0000-lmdb-predicate-guarantees branch.
 */
public class StandardPipelineReviewReproTest {

	private static final String PREFIX = "PREFIX : <http://ex/>\n";

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private void load(String trig) throws Exception {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader("@prefix : <http://ex/> .\n" + trig), "http://ex/", RDFFormat.TRIG);
		}
	}

	private List<String> rows(String query, String... vars) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIX + query);
			System.out.println("=== query ===\n" + query);
			System.out.println(tupleQuery.explain(Explanation.Level.Optimized));
			List<String> result = new ArrayList<>();
			try (TupleQueryResult res = tupleQuery.evaluate()) {
				for (BindingSet bs : res) {
					StringBuilder sb = new StringBuilder();
					for (String var : vars) {
						sb.append(var).append('=').append(bs.getValue(var)).append(' ');
					}
					result.add(sb.toString().trim());
				}
			}
			return result.stream().sorted().collect(Collectors.toList());
		}
	}

	private static StringBuilder filler(String predicate, int count) {
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < count; i++) {
			sb.append(":f").append(i).append(' ').append(predicate).append(" :fv").append(i).append(" .\n");
		}
		return sb;
	}

	// Candidate 1: VALUES pushed through a scope-changing BIND observes boundness inside the scope.
	@Test
	public void valuesPushedThroughScopedBindBreaksNotBound() throws Exception {
		load(":g { :s1 :p :o1 . " + filler(":p", 0) + "}\n");
		String query = "SELECT ?x ?s ?one WHERE {\n"
				+ "  VALUES ?x { :a :b }\n"
				+ "  { GRAPH :g { VALUES ?x { UNDEF } ?s :p ?o FILTER(!BOUND(?x)) } BIND(1 AS ?one) }\n"
				+ "}";
		// inner group: x unbound -> filter true -> (s1, one=1); joined with VALUES x in {a,b} -> 2 rows
		assertEquals(List.of("x=http://ex/a s=http://ex/s1 one=\"1\"^^<http://www.w3.org/2001/XMLSchema#integer>",
				"x=http://ex/b s=http://ex/s1 one=\"1\"^^<http://www.w3.org/2001/XMLSchema#integer>"),
				rows(query, "x", "s", "one"));
	}

	@Test
	public void valuesPushedThroughScopedBindBreaksNotExists() throws Exception {
		load(":g { :s1 :p :o1 . :s1 :q :c . }\n");
		String query = "SELECT ?x ?s WHERE {\n"
				+ "  VALUES ?x { :a :b }\n"
				+ "  { GRAPH :g { VALUES ?x { UNDEF } ?s :p ?o FILTER NOT EXISTS { ?s :q ?x } } BIND(1 AS ?one) }\n"
				+ "}";
		// inner group: x unbound -> NOT EXISTS { :s1 :q ?x } is false (:c exists) -> no rows
		assertEquals(List.of(), rows(query, "x", "s"));
	}

	@Test
	public void valuesThroughScopedBindControlWithoutPush() throws Exception {
		// control: BIND expression mentions ?x, so the normalizer must not push the VALUES (develop behaviour)
		load(":g { :s1 :p :o1 . }\n");
		String query = "SELECT ?x ?s WHERE {\n"
				+ "  VALUES ?x { :a :b }\n"
				+ "  { GRAPH :g { VALUES ?x { UNDEF } ?s :p ?o FILTER(!BOUND(?x)) } BIND(COALESCE(?x, 1) AS ?one) }\n"
				+ "}";
		assertEquals(List.of("x=http://ex/a s=http://ex/s1", "x=http://ex/b s=http://ex/s1"), rows(query, "x", "s"));
	}

	// Candidate 2: filter pushed onto a LeftJoin whose optional var is bound only by the sibling join operand.
	@Test
	public void filterPushedOntoLeftJoinLosesRows() throws Exception {
		load(":s1 :p :v . :s1 :r :v .\n" + filler(":r", 200));
		String query = "SELECT ?s ?x ?y WHERE { ?s :p ?y OPTIONAL { ?s :q ?x } ?s :r ?x FILTER(?x = ?y) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v y=http://ex/v"), rows(query, "s", "x", "y"));
	}

	// Candidate 4: sameTerm inside EXISTS referencing an outer variable.
	@Test
	public void sameTermInsideExistsWithOuterVar() throws Exception {
		load(":s1 :p :v1 . :s1 :q :o1 .\n");
		String query = "SELECT ?s WHERE { ?s :p ?x FILTER EXISTS { ?s :q ?o FILTER(sameTerm(?x, :v1)) } }";
		assertEquals(List.of("s=http://ex/s1"), rows(query, "s"));
	}

	// Candidate 4b: ORDER BY EXISTS with an unprojected variable.
	@Test
	public void orderByExistsUnprojectedVar() throws Exception {
		load(":s1 :p :o1 . :s2 :p :o2 . :o2 :q :z .\n");
		String query = "SELECT ?s WHERE { ?s :p ?o } ORDER BY DESC(EXISTS { ?o :q ?z }) ?s";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<String> ordered = new ArrayList<>();
			try (TupleQueryResult res = conn.prepareTupleQuery(PREFIX + query).evaluate()) {
				for (BindingSet bs : res) {
					ordered.add(bs.getValue("s").stringValue());
				}
			}
			assertEquals(List.of("http://ex/s2", "http://ex/s1"), ordered);
		}
	}

	// Candidate 5: sameTerm inlining with a VALUES column that has UNDEF (assured-name semantics).
	@Test
	public void sameTermWithUndefValuesColumn() throws Exception {
		load(":s1 :p :v .\n");
		String query = "SELECT ?s ?x WHERE { VALUES ?x { UNDEF :w } ?s :p ?x FILTER(sameTerm(?x, :v)) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v"), rows(query, "s", "x"));
	}

	@Test
	public void sameTermWithUndefValuesColumnTwoVars() throws Exception {
		load(":s1 :p :v .\n");
		String query = "SELECT ?s ?x ?y WHERE { VALUES (?x ?y) { (UNDEF :a) (:w :b) } ?s :p ?x FILTER(sameTerm(?x, :v)) }";
		assertEquals(List.of("s=http://ex/s1 x=http://ex/v y=http://ex/a"), rows(query, "s", "x", "y"));
	}
}
